import{_ as i,b as o,c as r,g as s}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"做简单决策","description":"","frontmatter":{"title":"做简单决策","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/16.md","filePath":"articles/ai/books/ai-modern-approach/16.md"}'),l={name:"articles/ai/books/ai-modern-approach/16.md"};function a(n,t,e,d,g,p){return o(),r("div",null,[...t[0]||(t[0]=[s('<p>第 16 章聚焦于单步决策（一次性决策），在不确定性下利用效用理论和决策网络进行理性选择。核心内容如下：</p><h2 id="效用基础" tabindex="-1">效用基础</h2><ul><li><strong>效用函数</strong>将状态映射为实数，表示智能体对该状态的偏好</li><li><strong>最大期望效用（MEU）原则</strong>：智能体应选择使期望效用最大的动作</li><li>理性决策的基本公式：MEU = maxₐ Σₛ P(s|a) U(s)</li></ul><h2 id="决策网络-影响图" tabindex="-1">决策网络（影响图）</h2><p>一种贝叶斯网络的扩展，包含三类节点：</p><ul><li><strong>机遇节点（圆形）</strong>：随机变量</li><li><strong>决策节点（矩形）</strong>：智能体可选择的动作</li><li><strong>效用节点（菱形）</strong>：表示效用函数，父节点为影响效用的变量</li></ul><p>对每个决策策略，计算期望效用以评价网络。</p><h2 id="效用函数的设计" tabindex="-1">效用函数的设计</h2><ul><li><strong>序数效用</strong>（仅排序）与<strong>基数效用</strong>（可比较差值）</li><li><strong>货币效用</strong>：钱与效用的关系（风险偏好：风险中性、风险厌恶、风险寻求）</li><li><strong>多属性效用函数</strong>：分解为加法或乘法形式，通过独立性假设简化评估</li><li>偏好独立、效用独立等概念</li></ul><h2 id="信息价值" tabindex="-1">信息价值</h2><ul><li><strong>完全信息价值（VPI）</strong>：获取某个变量的确切信息后决策所能带来的期望效用增益</li><li>VPI 永远非负，且非可加性（两个信息合起来的价值可能小于分别价值之和）</li><li>用于决定是否值得收集额外信息</li></ul>',11)])])}const u=i(l,[["render",a]]);export{c as __pageData,u as default};
